#!/bin/bash
# Pulls the current dark-surface color noctalia already generated for niri's
# window borders (~/.config/niri/noctalia.kdl, regenerated by noctalia on
# every palette change) and reuses it as the Overview backdrop color, since
# noctalia has no template of its own for niri's `overview` block.
# Run automatically via noctalia's hooks.colors_changed (settings.toml).

set -euo pipefail

CONFIG="$HOME/.config/niri/config.kdl"
SOURCE="$HOME/.config/niri/noctalia.kdl"

color=$(grep -m1 -oP 'inactive-color\s+"\K#[0-9a-fA-F]{6,8}' "$SOURCE") || exit 0
[ -n "$color" ] || exit 0

sed -i "s/backdrop-color \"#[0-9a-fA-F]\{6,8\}\"/backdrop-color \"$color\"/" "$CONFIG"

niri msg action load-config-file >/dev/null 2>&1 || true
